B.aoc=new A.c3(1,"Ba\u015flang\u0131\xe7","Bug\xfcn ne yedi\u011fini sadece kaydet, hi\xe7bir \u015feyi de\u011fi\u015ftirme.","Bug\xfcnk\xfc ad\u0131m say\u0131n\u0131 not et (ba\u015flang\u0131\xe7 de\u011ferin).","Neden kay\u0131t tutar\u0131z?",'Fark etmek de\u011fi\u015fimin ilk ad\u0131m\u0131d\u0131r. Kay\u0131t tutmak "iyi" ya da "k\xf6t\xfc" demek i\xe7in de\u011fil, g\xfcn\xfcn nas\u0131l akt\u0131\u011f\u0131n\u0131 g\xf6rmek i\xe7in. Bug\xfcn sadece g\xf6zlemci ol.',"Bug\xfcn sadece g\xf6zlemci ol. Yarg\u0131 yok, sadece merak.")
B.anH=new A.c3(2,"Su","Ki\u015fisel su hedefinin yar\u0131s\u0131n\u0131 \xf6\u011flene kadar i\xe7.","Ba\u015flang\u0131\xe7 ad\u0131m\u0131na +1.000 ad\u0131m ekle.","Susuzluk ve a\xe7l\u0131k neden kar\u0131\u015f\u0131r?","Hafif susuzluk bazen a\xe7l\u0131k ya da yorgunluk gibi hissedilir. A\xe7\u0131k sar\u0131 idrar rengi yeterli su i\xe7ti\u011finin basit bir i\u015faretidir. Su, ayran, maden suyu ve \u015fekersiz bitki \xe7ay\u0131 hedefe say\u0131l\u0131r.","Bir bardak su, kendine verdi\u011fin ilk s\xf6z.")
B.anQ=new A.c3(3,"\u0130lk \xf6\u011f\xfcn","\u0130lk \xf6\u011f\xfcne bir protein kayna\u011f\u0131 ekle (yumurta, peynir, yo\u011furt, baklagil).","10 dk tempolu y\xfcr\xfcy\xfc\u015f.","Protein toklu\u011fu nas\u0131l uzat\u0131r?","Protein sindirimi daha uzun s\xfcrer ve tokluk hissini destekler. G\xfcne protein i\xe7eren bir \xf6\u011f\xfcnle ba\u015flamak, \xf6\u011flene kadar daha dengeli bir i\u015ftah sa\u011flayabilir.","Sabah verdi\u011fin karar g\xfcn\xfcn geri kalan\u0131n\u0131 kolayla\u015ft\u0131r\u0131r.")
B.anF=new A.c3(4,"Tabak modeli","Bir \xf6\u011f\xfcnde taba\u011f\u0131n yar\u0131s\u0131n\u0131 sebzeyle doldur.","10 dk y\xfcr\xfcy\xfc\u015f + 5 dk esneme.","Sa\u011fl\u0131kl\u0131 tabak","Taba\u011f\u0131n yar\u0131s\u0131 sebze, \xe7eyre\u011fi protein (et, tavuk, bal\u0131k, yumurta, baklagil), \xe7eyre\u011fi tam tah\u0131l. Yan\u0131na bir kase yo\u011furt ve su. Hi\xe7bir \u015feyi \xe7\u0131karm\u0131yor, bir \u015fey ekliyoruz.","Bir \u015feyi \xe7\u0131karmak yerine bir \u015fey ekliyoruz.")
B.aog=new A.c3(5,"\xd6\u011f\xfcn saatleri","\xd6\u011f\xfcnler aras\u0131nda 3\u20135 saat b\u0131rakmay\u0131 dene, saatleri kaydet.","2 kez 10 dk y\xfcr\xfcy\xfc\u015f ya da merdiven.","D\xfczenli \xf6\u011f\xfcn ve ak\u015fam at\u0131\u015ft\u0131rmas\u0131","G\xfcn i\xe7inde uzun s\xfcre a\xe7 kalmak ak\u015fam saatlerinde yo\u011fun bir a\xe7l\u0131\u011fa yol a\xe7abilir. D\xfczenli aral\u0131klarla yemek, ak\u015fam at\u0131\u015ft\u0131rmas\u0131n\u0131 azaltman\u0131n en kolay yollar\u0131ndan biridir.","V\xfccudun d\xfczeni sever; sen de ona d\xfczen ver.")
B.anW=new A.c3(6,"Yava\u015f yemek","Bir \xf6\u011f\xfcn\xfc ekrans\u0131z ve en az 15 dakikada ye.","15 dk y\xfcr\xfcy\xfc\u015f.","Tokluk sinyali ne zaman gelir?","Mideden beyne giden tokluk sinyalleri yeme\u011fe ba\u015flad\u0131ktan yakla\u015f\u0131k 20 dakika sonra belirginle\u015fir. Yava\u015f yemek, doydu\u011funu fark etmeni kolayla\u015ft\u0131r\u0131r.","Yeme\u011fin tad\u0131n\u0131 almak da bir sa\u011fl\u0131k davran\u0131\u015f\u0131.")
B.aof=new A.c3(7,"Geri bak\u0131\u015f","Haftay\u0131 de\u011ferlendir: en kolay ve en zor al\u0131\u015fkanl\u0131k hangisiydi?","Bu haftan\u0131n en uzun y\xfcr\xfcy\xfc\u015f\xfcn\xfc tekrar et.","7 g\xfcnden sonra ne olur?","Bir ara\u015ft\u0131rmada yeni bir davran\u0131\u015f\u0131n otomatikle\u015fmesi ortalama 66 g\xfcn s\xfcrd\xfc (ki\u015fiden ki\u015fiye 18\u2013254 g\xfcn). Yedi g\xfcn bir ba\u015flang\u0131\xe7; en kolay al\u0131\u015fkanl\u0131\u011f\u0131n\u0131 se\xe7 ve s\xfcrd\xfcr.","Yedi g\xfcn\xfc tamamlad\u0131n. Asl\u0131nda ba\u015flad\u0131n.")
B.azR=s([B.aoc,B.anH,B.anQ,B.anF,B.aog,B.anW,B.aof],t.nF)
B.Hm=new A.iV(7,"Ba\u015flang\u0131\xe7 Haftas\u0131: Kendine D\xf6n","Ba\u015ftan ba\u015flamak de\u011fil, kendine d\xf6nmek.","Ne yapaca\u011f\u0131n\u0131 bilmeyen, d\xfczensiz yiyen, ilk ad\u0131m\u0131 arayanlar","Su, d\xfczenli \xf6\u011f\xfcn, tabak modeli, g\xfcnl\xfck y\xfcr\xfcy\xfc\u015f",B.azR)
B.anP=new A.c3(1,"Ba\u015flang\u0131\xe7","\xd6\u011f\xfcn, uyku ve enerji g\xfcnl\xfc\u011f\xfc ba\u015flat.","Ba\u015flang\u0131\xe7 ad\u0131m\u0131n\u0131 kaydet.","Kamp neyi \xf6l\xe7er?","Bu kamp\u0131n ba\u015far\u0131 \xf6l\xe7\xfct\xfc tart\u0131 de\u011fil, g\xfcnl\xfck davran\u0131\u015f: g\xf6rev tamamlama, enerji, uyku ve tok hissetme.",u.L)
B.anL=new A.c3(2,"Su","Ki\u015fisel su hedefini tamamla.","+1.000 ad\u0131m.","Su hedefin nas\u0131l hesapland\u0131?","Hedefin kilonun her 30 kilogram\u0131 i\xe7in yakla\u015f\u0131k 1 litre \xfczerinden hesaplan\u0131r ve 1,5\u20133,5 litre aras\u0131nda tutulur. Hareket etti\u011fin g\xfcn biraz artar. Sa\u011fl\u0131k durumun gerektiriyorsa hedefi diyetisyenin belirler.",u.L)
B.ao7=new A.c3(3,"\u0130lk \xf6\u011f\xfcn","\u0130lk \xf6\u011f\xfcne protein + lif ekle.","15 dk y\xfcr\xfcy\xfc\u015f.","Kahvalt\u0131 \u015fart m\u0131?","Kahvalt\u0131n\u0131n herkes i\xe7in \u015fart oldu\u011funu g\xf6steren g\xfc\xe7l\xfc bir kan\u0131t yok. \xd6nemli olan g\xfcn\xfcn ilk \xf6\u011f\xfcn\xfcn\xfcn dengeli olmas\u0131 ve sana iyi gelen bir d\xfczen.",u.L)
B.anK=new A.c3(4,"Tabak modeli","\u0130ki \xf6\u011f\xfcnde taba\u011f\u0131n yar\u0131s\u0131 sebze olsun.","15 dk y\xfcr\xfcy\xfc\u015f + esneme.","Sebzede renk \xe7e\u015fitlili\u011fi","Farkl\u0131 renkteki sebze ve meyveler farkl\u0131 vitamin, mineral ve bitki bile\u015fenleri ta\u015f\u0131r. Haftada m\xfcmk\xfcn oldu\u011funca \xe7ok renk hedefle.",u.L)
B.anN=new A.c3(5,"Lif","G\xfcnde 1 kez baklagil ye.","10 dk g\xfc\xe7 hareketi.","Lif ve tokluk","Mercimek, nohut ve fasulye hem lif hem protein kayna\u011f\u0131d\u0131r; toklu\u011fu destekler ve ekonomiktir.",u.L)
B.aod=new A.c3(6,"\u015eekerli i\xe7ecek","\u015eekerli i\xe7ecek yerine maden suyu-limon ya da ayran se\xe7.","20 dk y\xfcr\xfcy\xfc\u015f.","Gizli \u015feker","Bir kutu (330 mL) kola yakla\u015f\u0131k 35 g, yani 7\u20138 k\xfcp \u015feker i\xe7erir. \u0130\xe7ecekten gelen \u015feker tokluk hissi vermeden enerji ekler.",u.L)
B.anY=new A.c3(7,"Hafta 1 geri bak\u0131\u015f",'En kolay al\u0131\u015fkanl\u0131\u011f\u0131n\u0131 se\xe7 ve "sabit" olarak i\u015faretle.',"Haftan\u0131n en uzun y\xfcr\xfcy\xfc\u015f\xfcn\xfc tekrarla.","Al\u0131\u015fkanl\u0131k d\xf6ng\xfcs\xfc","Al\u0131\u015fkanl\u0131k \xfc\xe7 par\xe7adan olu\u015fur: tetik, davran\u0131\u015f, \xf6d\xfcl. Ayn\u0131 tetikle ayn\u0131 davran\u0131\u015f\u0131 tekrarlamak onu zamanla otomatikle\u015ftirir.",u.L)
B.anO=new A.c3(8,"Uyku","Yat\u0131\u015f saatini sabitle, yatmadan 30 dk \xf6nce ekran\u0131 b\u0131rak.","20 dk y\xfcr\xfcy\xfc\u015f.","Uyku ve i\u015ftah","K\u0131sa uyku, i\u015ftah\u0131 d\xfczenleyen hormonlar\u0131 etkileyebilir ve ertesi g\xfcn y\xfcksek enerjili yiyecek iste\u011fini art\u0131rabilir.",u.U)
B.anI=new A.c3(9,"A\xe7l\u0131k \xf6l\xe7e\u011fi","Her \xf6\u011f\xfcn \xf6ncesi ve sonras\u0131 a\xe7l\u0131\u011f\u0131n\u0131 1\u201310 aras\u0131nda puanla.","10 dk g\xfc\xe7 + esneme.","Fiziksel ve duygusal a\xe7l\u0131k","Fiziksel a\xe7l\u0131k yava\u015f gelir ve herhangi bir yiyecekle ge\xe7er. Duygusal a\xe7l\u0131k ani gelir, belirli bir yiyecek ister ve doyduktan sonra da s\xfcrebilir.",u.U)
B.aoa=new A.c3(10,"Tetikleyiciler","Plans\u0131z yedi\u011fin bir an\u0131 yaz: saat, yer, duygu.","20 dk y\xfcr\xfcy\xfc\u015f.","Duygusal yeme bir sinyaldir","Duygusal yeme su\xe7 de\u011fil; bir ihtiyac\u0131n sinyalidir. Tetikleyiciyi fark etmek, ona ba\u015fka bir yan\u0131t vermenin ilk ad\u0131m\u0131d\u0131r.","Plans\u0131z bir an ya\u015fad\u0131ysan, ba\u015far\u0131s\u0131zl\u0131k de\u011fil, veri toplad\u0131n.")
B.ao9=new A.c3(11,"Stres","4-7-8 nefes egzersizini g\xfcnde 2 kez yap.","15 dk do\u011fada y\xfcr\xfcy\xfc\u015f.","Stres ve i\u015ftah","Stres baz\u0131 ki\u015filerde i\u015ftah\u0131 art\u0131r\u0131r, baz\u0131lar\u0131nda azalt\u0131r. K\u0131sa nefes egzersizleri ve y\xfcr\xfcy\xfc\u015f, stres an\u0131nda yeme\u011fe alternatif olabilir.",u.U)
B.ao5=new A.c3(12,"Alternatif davran\u0131\u015f","Tetikleyici an i\xe7in 3 alternatif yaz (y\xfcr\xfcy\xfc\u015f, arama, du\u015f).","25 dk y\xfcr\xfcy\xfc\u015f.",'"E\u011fer-o zaman" plan\u0131','"E\u011fer ak\u015fam can\u0131m tatl\u0131 isterse, o zaman \xf6nce bir bardak su i\xe7ip 5 dakika y\xfcr\xfcyece\u011fim" gibi \xf6nceden yap\u0131lm\u0131\u015f planlar davran\u0131\u015f\u0131 de\u011fi\u015ftirmeyi kolayla\u015ft\u0131r\u0131r.',u.U)
B.ao2=new A.c3(13,"Yava\u015f yemek","2 \xf6\u011f\xfcn\xfc ekrans\u0131z ye.","10 dk g\xfc\xe7 hareketi.","Fark\u0131ndal\u0131kla yeme","Yeme\u011fin rengine, kokusuna ve tad\u0131na dikkat etmek hem keyfi art\u0131r\u0131r hem de toklu\u011fu fark etmeyi kolayla\u015ft\u0131r\u0131r.",u.U)
B.anG=new A.c3(14,"Hafta 2 geri bak\u0131\u015f","Uyku ve enerji puanlar\u0131n\u0131 Hafta 1 ile k\u0131yasla.","Sevdi\u011fin hareketi tekrarla.","Kendine \u015fefkat","Kendine \u015fefkatle yakla\u015fan ki\u015filerin kayma sonras\u0131 yeniden ba\u015flamas\u0131 daha kolayd\u0131r. M\xfckemmel de\u011fil, s\xfcrd\xfcr\xfclebilir.","Yar\u0131 yoldan fazlas\u0131n\u0131 ge\xe7tin. En zor k\u0131s\u0131m genelde tam buras\u0131d\u0131r ve sen buradas\u0131n.")
B.ao3=new A.c3(15,"Men\xfc planlama","Haftal\u0131k men\xfc \u015fablonunu doldur.","25 dk y\xfcr\xfcy\xfc\u015f.","Plan \u015fablonu nas\u0131l kullan\u0131l\u0131r?","\xd6nce ana \xf6\u011f\xfcnlerin protein kayna\u011f\u0131n\u0131 se\xe7, sonra sebze ve tah\u0131l\u0131 ekle. Ayn\u0131 yeme\u011fi iki g\xfcn kullanmak plan\u0131 kolayla\u015ft\u0131r\u0131r.",u.N)
B.anJ=new A.c3(16,"Al\u0131\u015fveri\u015f","Listeyle al\u0131\u015fveri\u015fe git, etiket oku.","15 dk g\xfc\xe7 hareketi.","Etiket okuma","100 g ba\u015f\u0131na \u015feker, tuz ve doymu\u015f ya\u011f de\u011ferlerini kar\u015f\u0131la\u015ft\u0131r. \u0130\xe7indekiler listesinin ilk \xfc\xe7 maddesi \xfcr\xfcn\xfcn \xe7o\u011funu olu\u015fturur.",u.N)
B.ao4=new A.c3(17,"Haz\u0131rl\u0131k","30 dakikal\u0131k haftal\u0131k mutfak haz\u0131rl\u0131\u011f\u0131 yap.","25 dk y\xfcr\xfcy\xfc\u015f.","Toplu pi\u015firme ve saklama","Pi\u015fmi\u015f yeme\u011fi 2 saat i\xe7inde buzdolab\u0131na koy, 3\u20134 g\xfcn i\xe7inde t\xfcket ya da porsiyonlay\u0131p dondur.",u.N)
B.anZ=new A.c3(18,"Sosyal sofra","Davette ya da d\u0131\u015far\u0131da yemekte tabak modelini uygula.","Dans, bisiklet ya da y\xfcr\xfcy\xfc\u015f, 30 dk.","Dengede kalmak",u.G,u.C)
B.aob=new A.c3(19,"Hareketi sabitlemek","Haftal\u0131k hareket takvimini yaz (haftada 150 dk hedefi).","15 dk g\xfc\xe7 + 15 dk y\xfcr\xfcy\xfc\u015f.","Ne kadar hareket?","D\xfcnya Sa\u011fl\u0131k \xd6rg\xfct\xfc yeti\u015fkinlere haftada en az 150\u2013300 dakika orta yo\u011funlukta hareket ve haftada 2 g\xfcn kas g\xfc\xe7lendirici egzersiz \xf6nerir.",u.N)
B.anR=new A.c3(20,"Zor g\xfcn plan\u0131",'Kendi "zor g\xfcn kiti"ni yaz: 3 kolay \xf6\u011f\xfcn, 1 hareket, 1 destek ki\u015fisi.',"30 dk y\xfcr\xfcy\xfc\u015f.","Kayma normaldir","Her rutin zaman zaman aksar. \xd6nemli olan geri d\xf6n\xfc\u015f plan\u0131n\u0131n haz\u0131r olmas\u0131.",u.N)
B.ao0=new A.c3(21,"Devam plan\u0131","3 sabit al\u0131\u015fkanl\u0131k se\xe7 ve 2 hafta sonras\u0131 i\xe7in kontrol tarihi koy.","Kutlama y\xfcr\xfcy\xfc\u015f\xfc.","66 g\xfcn ger\xe7e\u011fi","21 g\xfcnde al\u0131\u015fkanl\u0131k tamamen oturmaz; ara\u015ft\u0131rmalarda ortalama 66 g\xfcn bulundu. Kamp temeli att\u0131, \u015fimdi s\xfcrd\xfcrme d\xf6nemi ba\u015fl\u0131yor.","Bu kamp bitti, senin rutinin bitmedi. Kendi plan\u0131n\u0131 yazd\u0131n; art\u0131k yol senin.")
B.auf=s([B.anP,B.anL,B.ao7,B.anK,B.anN,B.aod,B.anY,B.anO,B.anI,B.aoa,B.ao9,B.ao5,B.ao2,B.anG,B.ao3,B.anJ,B.ao4,B.anZ,B.aob,B.anR,B.ao0],t.nF)
B.aoi=new A.iV(21,"Al\u0131\u015fkanl\u0131k Kamp\u0131: Kal\u0131c\u0131 De\u011fi\u015fim","Kurallar de\u011fil, rutinler.","Daha \xf6nce diyet yap\u0131p b\u0131rakan, s\xfcrd\xfcr\xfclebilir bir d\xfczen isteyenler","Uyku, stres, duygusal yeme, haz\u0131rl\u0131k rutini ve kamp sonras\u0131 devam plan\u0131",B.auf)
B.anM=new A.c3(1,"Ba\u015flang\u0131\xe7","3 \xf6\u011f\xfcn\xfc foto\u011frafla kaydet, sadece g\xf6zlemle.","Ba\u015flang\u0131\xe7 ad\u0131m say\u0131n\u0131 kaydet.","Dengeli sofra nedir?","T\xfcrkiye Beslenme Rehberi (T\xdcBER) dengeli tabakta sebze-meyve, tam tah\u0131l, protein kaynaklar\u0131 ve s\xfct grubunun bir arada olmas\u0131n\u0131 \xf6nerir. Bug\xfcn sadece sofrana bak.","On be\u015f g\xfcn boyunca kendi sofran\u0131n mimar\u0131s\u0131n.")
B.anX=new A.c3(2,"Protein","Her ana \xf6\u011f\xfcnde avu\xe7 i\xe7i kadar bir protein kayna\u011f\u0131 olsun.","20 dk y\xfcr\xfcy\xfc\u015f.","Neden \xf6nce protein?","Protein toklu\u011fu en uzun tutan besin \xf6gesidir ve kilo verirken kas kayb\u0131n\u0131 azaltmaya yard\u0131m eder. Bu kampta karbonhidrat saym\u0131yoruz; \xf6nce protein ve life bak\u0131yoruz.",u.x)
B.anU=new A.c3(3,"Lif","G\xfcne en az 1 kez baklagil ya da tam tah\u0131l ekle.","20 dk y\xfcr\xfcy\xfc\u015f + 5 dk esneme.","Lif ve tokluk","Lif toklu\u011fu destekler ve ba\u011f\u0131rsak sa\u011fl\u0131\u011f\u0131 i\xe7in \xf6nemlidir. Yeti\u015fkinler i\xe7in g\xfcnl\xfck yakla\u015f\u0131k 25 g lif \xf6nerilir (EFSA); baklagil, sebze, meyve ve tam tah\u0131llar iyi kaynaklard\u0131r.",u.x)
B.aoe=new A.c3(4,"Protein da\u011f\u0131l\u0131m\u0131","Proteini g\xfcne yay: kahvalt\u0131, \xf6\u011fle ve ak\u015famda ayr\u0131 kaynak se\xe7.","Evde 10 dk g\xfc\xe7 hareketi (duvara \u015f\u0131nav, sandalyeden kalk\u0131\u015f).","Proteini g\xfcne yaymak","Proteini tek \xf6\u011f\xfcnde toplamak yerine \xf6\u011f\xfcnlere yaymak toklu\u011fu ve kas sa\u011fl\u0131\u011f\u0131n\u0131 destekler. Yumurta, yo\u011furt, peynir, baklagil, bal\u0131k ve tavuk d\xf6n\xfc\u015f\xfcml\xfc kullan\u0131labilir.",u.x)
B.ao_=new A.c3(5,"Sebze yar\u0131s\u0131","\u0130ki \xf6\u011f\xfcnde taba\u011f\u0131n yar\u0131s\u0131n\u0131 sebzeyle doldur.","25 dk y\xfcr\xfcy\xfc\u015f.","Hacim ve tokluk","Sebzeler az enerjiyle \xe7ok hacim ve lif sa\u011flar. Taba\u011f\u0131n yar\u0131s\u0131 sebze olunca ayn\u0131 toklu\u011fa daha dengeli bir tabakla ula\u015f\u0131rs\u0131n.",u.x)
B.anE=new A.c3(6,"Planlama","Yar\u0131nki 3 \xf6\u011f\xfcn\xfc bu ak\u015fam yaz.","20 dk y\xfcr\xfcy\xfc\u015f.","Plan neden i\u015fe yarar?","Ne yiyece\u011fini \xf6nceden bilmek g\xfcn i\xe7indeki karar y\xfck\xfcn\xfc azalt\u0131r. Plan bir kural de\u011fil, yar\u0131nki sana b\u0131rakt\u0131\u011f\u0131n bir nottur.",u.P)
B.ao8=new A.c3(7,"Etiket okuma","Evdeki 3 paketli \xfcr\xfcn\xfcn etiketinde \u015feker, tuz ve lif miktar\u0131n\u0131 bul.","25 dk y\xfcr\xfcy\xfc\u015f.","Etiket nas\u0131l okunur?","\xdcr\xfcnleri kar\u015f\u0131la\u015ft\u0131r\u0131rken 100 g ba\u015f\u0131na de\u011ferlere bak: \u015feker, tuz, doymu\u015f ya\u011f ve lif. \u0130\xe7indekiler listesi en \xe7ok bulunandan en aza do\u011fru s\u0131ralan\u0131r.",u.P)
B.ao6=new A.c3(8,"A\xe7l\u0131k-tokluk","Yeme\u011fe ba\u015flamadan ve bitirince a\xe7l\u0131\u011f\u0131n\u0131 1\u201310 aras\u0131nda puanla.","20 dk y\xfcr\xfcy\xfc\u015f + esneme.","A\xe7l\u0131k \xf6l\xe7e\u011fi","Fiziksel a\xe7l\u0131k yava\u015f gelir ve herhangi bir yiyecekle ge\xe7er; duygusal a\xe7l\u0131k ani gelir ve belirli bir yiyecek ister. Puanlamak fark\u0131 g\xf6rmeni kolayla\u015ft\u0131r\u0131r.","V\xfccudunu dinlemek bir beceri; her g\xfcn biraz daha iyi duyacaks\u0131n.")
B.anB=new A.c3(9,"Ak\u015fam rutini",'Ak\u015fam yeme\u011finden sonra mutfa\u011f\u0131 "kapat": di\u015f f\u0131r\xe7ala, bitki \xe7ay\u0131 haz\u0131rla.',"10 dk ak\u015fam y\xfcr\xfcy\xfc\u015f\xfc.","Gece at\u0131\u015ft\u0131rmas\u0131 nereden gelir?","Gece at\u0131\u015ft\u0131rmas\u0131n\u0131n s\u0131k nedenlerinden biri g\xfcn i\xe7inde yetersiz yemektir. Ak\u015fam\u0131n huzurlu ge\xe7mesi g\xfcnd\xfcz d\xfczenli ve proteinli beslenmekle ba\u015flar.","Ak\u015fam\u0131n huzurlu ge\xe7mesi, g\xfcnd\xfcz iyi beslenmekle ba\u015flar.")
B.anS=new A.c3(10,"Haz\u0131rl\u0131k","Hafta haz\u0131rl\u0131\u011f\u0131: 1 baklagil ha\u015fla, 1 sebze do\u011fra, 1 sos haz\u0131rla.","Evde 15 dk g\xfc\xe7 + esneme.","Haz\u0131rl\u0131k yapan mutfak","\xd6nceden haz\u0131rlanm\u0131\u015f birka\xe7 temel malzeme, yorgun bir ak\u015famda haz\u0131r g\u0131daya uzanma ihtiyac\u0131n\u0131 azalt\u0131r.","Bug\xfcnk\xfc 30 dakika, haftan\u0131n 3 saatini kurtar\u0131r.")
B.ao1=new A.c3(11,"Y\xf6resel sofran","Kendi y\xf6re mutfa\u011f\u0131ndan bir yeme\u011fi tabak modeline uydur.","25 dk y\xfcr\xfcy\xfc\u015f ya da halay, horon, zeybek: sevdi\u011fin bir dans.","Yasak yemek yok","Hamsi, karalahana, zeytinya\u011fl\u0131 otlar, bulgur, mercimek, tarhana... Her y\xf6renin mutfa\u011f\u0131nda protein ve lif zengini yemekler var. Ki\u015fisel plan\u0131n senin sofrana g\xf6re haz\u0131rlan\u0131r.",u.H)
B.anC=new A.c3(12,"D\u0131\u015far\u0131da yemek","D\u0131\u015far\u0131da ya da paket servis yerken \xf6nce proteini ve sebzeyi se\xe7.","25 dk y\xfcr\xfcy\xfc\u015f ya da dans.","Men\xfcden se\xe7im","Izgara, ha\u015flama ve f\u0131r\u0131n y\xf6ntemlerini se\xe7; yan\u0131na salata ya da sebze ekle. Sosu ayr\u0131 istemek k\xfc\xe7\xfck ama etkili bir ad\u0131m.",u.H)
B.anV=new A.c3(13,"Sosyal sofra","Davette ya da misafirlikte taba\u011f\u0131n\u0131 sebzeyle ba\u015flat, yava\u015f ye.","20 dk y\xfcr\xfcy\xfc\u015f + 10 dk g\xfc\xe7.","Dengede kalmak",u.G,u.C)
B.anD=new A.c3(14,"Zor g\xfcn kiti",'Kendi "zor g\xfcn kiti"ni yaz: 3 kolay proteinli \xf6\u011f\xfcn, 1 hareket, 1 destek ki\u015fisi.',"30 dk y\xfcr\xfcy\xfc\u015f.","Kayma normaldir","Her rutin zaman zaman aksar. \xd6nemli olan geri d\xf6n\xfc\u015f plan\u0131n\u0131n haz\u0131r olmas\u0131. Bir kayma, kamp\u0131n bitti\u011fi anlam\u0131na gelmez.",u.H)
B.anT=new A.c3(15,"Kendi men\xfcn","Gelecek haftan\u0131n men\xfcs\xfcn\xfc protein + lif \u015fablonuyla planla.","15 g\xfcn\xfcn en sevdi\u011fin hareketini tekrarla.","Kamp sonras\u0131","S\xfcrd\xfcr\xfclebilir olan, m\xfckemmel olandan iyidir. Bu on be\u015f g\xfcnde en kolay s\xfcrd\xfcrd\xfc\u011f\xfcn \xfc\xe7 al\u0131\u015fkanl\u0131\u011f\u0131 se\xe7 ve \xf6n\xfcm\xfczdeki haftaya ta\u015f\u0131.","On be\u015f g\xfcn\xfc tamamlad\u0131n. Sofran art\u0131k seni tan\u0131yor.")
